Here is the commit message:
fix bug introduced by 306684d

Here is the root cause:
The bug was likely caused by the improper handling of the length of elements in the `tags` vector, which could lead to incorrect data being processed or stored. The absence of the `Rf_lengthgets` function call meant that the elements were not resized to the expected length, potentially causing issues when accessing or manipulating these elements later in the code.

Here is the patch:

 static void _grow_SCAN_BAM_DATA_tags(SEXP tags, int len)
 {
     int i, j;

     for (i = 0; i < LENGTH(tags); ++i) {
         SEXP elt = VECTOR_ELT(tags, i);
         if (R_NilValue == elt)
             continue;
         int len0 = LENGTH(elt);
+        elt = Rf_lengthgets(elt, len);
         SET_VECTOR_ELT(tags, i, elt);
         switch (TYPEOF(elt)) {
         case INTSXP:
             for (j = len0; j < len; ++j)
                 INTEGER(elt)[j] = NA_INTEGER;
             break;
         case REALSXP:
             for (j = len0; j < len; ++j)
                 REAL(elt)[j] = NA_REAL;
             break;
         case STRSXP:
             for (j = len0; j < len; ++j)
                 SET_STRING_ELT(elt, j, NA_STRING);
             break;
         case RAWSXP:
             for (j = len0; j < len; ++j)
                 RAW(elt)[j] = 0x0;
         default:
             break;
         }
     }
 }



